window.HOEREN_TESTS[76] = {"id":"bei-der-polizei","name":"Bei der Polizei","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist die Polizei. Wir haben Ihr gestohlenes Fahrrad gefunden — aber leider beschädigt, nicht wie neu. Das Vorderrad ist kaputt. Es ist also gefunden, nicht noch weg. Sie können es trotzdem abholen. Bringen Sie bitte Ihren Ausweis und den Kaufbeleg mit. Die Wache ist rund um die Uhr offen. Auf Wiederhören!","gender":"f","q":"In welchem Zustand ist das Fahrrad?","opts":["Wie neu.","Noch nicht gefunden.","Beschädigt, das Vorderrad ist kaputt."],"correct":2},{"transcript":"Hallo Tom, hier ist Markus. Pass auf, mir wurde die Geldbörse gestohlen — in der vollen Bahn, ich habe nichts gemerkt. Ich hatte keinen Unfall, und mein Auto ist auch nicht verloren. Jetzt muss ich zur Polizei und eine Anzeige machen, sonst sperrt die Bank meine Karte nicht. Kannst du mich abholen? Bitte ruf zurück!","gender":"m","q":"Was ist Markus passiert?","opts":["Er hat einen Unfall gehabt.","Er hat sein Auto verloren.","Seine Geldbörse wurde gestohlen."],"correct":2},{"transcript":"Achtung Bürger: Wegen eines Festes ist die Hauptstraße am Samstag gesperrt. Bitte parken Sie Ihr Auto nicht dort, sonst wird es abgeschleppt. Einen Zettel bekommen Sie nicht. Nutzen Sie die Parkhäuser in der Nähe. Die Polizei regelt den Verkehr. Vielen Dank für Ihr Verständnis!","gender":"m","q":"Was passiert mit falsch geparkten Autos?","opts":["Sie werden abgeschleppt.","Nichts.","Sie bekommen einen Zettel."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Vor unserem Haus wird seit Tagen sehr laut gefeiert, jede Nacht bis drei Uhr. Es ist Lärm in der Nacht, kein Einbruch und kein Diebstahl. Ich kann nicht schlafen. Ich habe schon mit den Nachbarn geredet, aber nichts hilft. Soll ich die Polizei rufen? Was würdest du machen? Melde dich!","gender":"f","q":"Was ist Annas Problem?","opts":["Ein Einbruch.","Lärm in der Nacht.","Ein Diebstahl."],"correct":1},{"transcript":"Liebe Bürger: Bitte seien Sie vorsichtig. In letzter Zeit gibt es viele falsche Anrufe. Es geht nicht um schnelle Autos und nicht um laute Feste. Jemand sagt, er sei von der Polizei und fragt nach Ihrem Geld oder Schmuck. Die echte Polizei fragt so etwas nie am Telefon. Legen Sie auf und rufen Sie uns an. Schützen Sie sich!","gender":"f","q":"Wovor warnt die Polizei?","opts":["Vor schnellen Autos.","Vor falschen Anrufen.","Vor lauten Festen."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer war warum dort? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Ich rufe aus der Stadt an. Warst du heute auch bei der Polizei?"},{"speaker":"Lisa","gender":"f","text":"Ich war am Morgen dort. Diese Woche ist wirklich viel passiert."},{"speaker":"Lukas","gender":"m","text":"Bei mir ist es auch so. Ich melde mein Fahrrad als gestohlen und mache eine Anzeige."},{"speaker":"Lisa","gender":"f","text":"Das rote Fahrrad vor dem Haus ist weg. Meldet jemand einen Einbruch in der Straße?"},{"speaker":"Lukas","gender":"m","text":"Einen Einbruch meldet bei uns keiner. Dort bleibt alles ruhig."},{"speaker":"Lisa","gender":"f","text":"Ich muss einen Autounfall melden. In der Stadt an der großen Ecke ist es passiert."},{"speaker":"Lukas","gender":"m","text":"Zum Glück ist es nicht schlimm. Was hat Tom bei der Polizei gemacht?"},{"speaker":"Lisa","gender":"f","text":"Tom hat eine Brieftasche gefunden und am Tisch abgegeben."},{"speaker":"Lukas","gender":"m","text":"Das finde ich richtig von ihm. Muss jemand einen Strafzettel bezahlen?"},{"speaker":"Lisa","gender":"f","text":"Einen Strafzettel bezahlt diese Woche auch keiner."},{"speaker":"Lukas","gender":"m","text":"Was ist mit Sara?"},{"speaker":"Lisa","gender":"f","text":"Sara hat sich über laute Nachbarn beschwert. Die Musik ging bis in die Nacht."},{"speaker":"Lukas","gender":"m","text":"Tim hat ein anderes Problem."},{"speaker":"Lisa","gender":"f","text":"Tim hat seinen Pass verloren. Er sucht ihn seit der Fahrt nach Berlin."},{"speaker":"Lukas","gender":"m","text":"Dann soll er morgen noch einmal kommen."},{"speaker":"Lisa","gender":"f","text":"Ich lege jetzt auf."}],"options":[{"letter":"a","text":"Fahrrad gestohlen — Anzeige"},{"letter":"b","text":"Brieftasche gefunden — abgegeben"},{"letter":"c","text":"Einbruch melden"},{"letter":"d","text":"Pass verloren"},{"letter":"e","text":"Strafzettel bezahlen"},{"letter":"f","text":"Über laute Nachbarn beschwert"},{"letter":"g","text":"Vermisste Person melden"},{"letter":"h","text":"Autounfall melden"},{"letter":"i","text":"Zeuge eines Unfalls"}],"items":[{"person":"Lukas","correct":"a"},{"person":"Lisa","correct":"h"},{"person":"Tom","correct":"b"},{"person":"Sara","correct":"f"},{"person":"Tim","correct":"d"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Bürgerin","gender":"f","text":"Guten Tag, ich möchte eine Anzeige machen. Es geht nicht um das Fahrrad und nicht um die Tasche."},{"speaker":"Polizist","gender":"m","text":"Worum geht es, um das Fahrrad oder die Tasche?"},{"speaker":"Bürgerin","gender":"f","text":"Mein Handy wurde gestohlen, nicht das Fahrrad und nicht die Tasche."},{"speaker":"Polizist","gender":"m","text":"Setzen Sie sich, ich nehme das auf. Also das Handy, nicht Fahrrad oder Tasche."},{"speaker":"Bürgerin","gender":"f","text":"Danke, das Handy ist weg. Ich warte hier."}],"q":"Was wurde gestohlen?","opts":["Das Handy.","Das Fahrrad.","Die Tasche."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, wann kann ich mein Auto abholen? Brauche ich nur Geld oder ein Foto?"},{"speaker":"Polizistin","gender":"f","text":"Es steht auf dem Hof hinten. Nur Geld oder ein Foto reicht nicht."},{"speaker":"Mann","gender":"m","text":"Was muss ich mitbringen, nur Geld?"},{"speaker":"Polizistin","gender":"f","text":"Den Fahrzeugschein und Ihren Ausweis, nicht nur Geld und kein Foto."},{"speaker":"Mann","gender":"m","text":"Gut, Fahrzeugschein und Ausweis. Dann komme ich gleich. Danke."}],"q":"Was muss der Mann mitbringen?","opts":["Nur Geld.","Fahrzeugschein und Ausweis.","Ein Foto."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, ich zeige nichts an und suche auch nichts. Ich habe diesen Schlüsselbund gefunden."},{"speaker":"Polizist","gender":"m","text":"Wo war das? Geben Sie einen Fund ab?"},{"speaker":"Frau","gender":"f","text":"Vor dem Supermarkt. Ich gebe den Fund ab, ich suche nichts."},{"speaker":"Polizist","gender":"m","text":"Danke, das ist sehr ehrlich von Ihnen. Sie geben den Fund bei uns ab."},{"speaker":"Frau","gender":"f","text":"Gern, ich gebe ihn ab. Ich zeige nichts an. Danke."}],"q":"Was macht die Frau?","opts":["Sie zeigt etwas an.","Sie gibt einen Fund ab.","Sie sucht etwas."],"correct":1},{"lines":[{"speaker":"Bürger","gender":"m","text":"Guten Tag, wie lange dauert die Anzeige? Zehn Minuten oder eine Stunde?"},{"speaker":"Polizistin","gender":"f","text":"Etwa zwanzig Minuten, nicht zehn Minuten und nicht eine Stunde."},{"speaker":"Bürger","gender":"m","text":"Bekomme ich eine Kopie nach zwanzig Minuten?"},{"speaker":"Polizistin","gender":"f","text":"Ja, eine Bestätigung für die Versicherung, nach etwa zwanzig Minuten."},{"speaker":"Bürger","gender":"m","text":"Gut, zwanzig Minuten sind okay. Danke für die Info."}],"q":"Wie lange dauert die Anzeige?","opts":["Zehn Minuten.","Eine Stunde.","Zwanzig Minuten."],"correct":2},{"lines":[{"speaker":"Anruferin","gender":"f","text":"Guten Tag, vor meinem Haus parkt ein fremdes Auto seit Wochen. Es ist kein Lärm und kein Einbruch."},{"speaker":"Polizist","gender":"m","text":"Steht es verkehrswidrig? Geht es um Lärm oder um einen Einbruch?"},{"speaker":"Anruferin","gender":"f","text":"Nein, aber es bewegt sich nie. Nur das fremde Auto, kein Lärm."},{"speaker":"Polizist","gender":"m","text":"Wir schauen uns das fremde Auto an, danke für den Hinweis. Kein Einbruch also."},{"speaker":"Anruferin","gender":"f","text":"Danke, bitte schauen Sie das Auto an. Das reicht mir."}],"q":"Worüber beschwert sich die Anruferin?","opts":["Über ein fremdes Auto.","Über Lärm.","Über einen Einbruch."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Keller, einem Polizisten. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Keller, Sie sind seit 20 Jahren Polizist. Was war Ihr Grund für diesen Beruf?"},{"speaker":"Keller","gender":"m","text":"Ich wollte den Menschen helfen und für Sicherheit sorgen. Viele denken bei Polizei nur an Verbrecher fangen. Aber das ist nur ein kleiner Teil. Den größten Teil meiner Arbeit mache ich für ganz normale Leute, die in Not sind oder Hilfe brauchen."},{"speaker":"Reporterin","gender":"f","text":"Was sind Ihre häufigsten Einsätze?"},{"speaker":"Keller","gender":"m","text":"Verkehrsunfälle, Streit zwischen Nachbarn, kleine Diebstähle. Große Verbrechen sind selten, zum Glück. Oft geht es einfach darum, dass Menschen sich nicht einig sind und wir vermitteln. Da bin ich mehr Schlichter als Polizist. Das überrascht viele Leute."},{"speaker":"Reporterin","gender":"f","text":"Was sollten die Bürger bei einem Diebstahl tun?"},{"speaker":"Keller","gender":"m","text":"Sofort zu uns kommen und Anzeige erstatten. Viele warten zu lange, dann ist die Spur kalt. Und sperren Sie sofort Ihre Karten. Wichtig ist auch: Notieren Sie sich die Nummern Ihrer Geräte. Mit der Nummer können wir ein gestohlenes Handy viel leichter finden."},{"speaker":"Reporterin","gender":"f","text":"Wie kann man sich am besten schützen?"},{"speaker":"Keller","gender":"m","text":"Aufmerksam sein, besonders im Gedränge. Die Geldbörse vorne tragen, nicht hinten. Türen abschließen, auch wenn man nur kurz weggeht. Und misstrauisch sein bei fremden Anrufen. Die meisten Diebstähle passieren, weil jemand kurz unaufmerksam war. Vorsicht hilft mehr als alles andere."},{"speaker":"Reporterin","gender":"f","text":"Was möchten Sie den Menschen sagen?"},{"speaker":"Keller","gender":"m","text":"Haben Sie keine Angst, uns zu rufen. Lieber einmal zu oft als zu spät. Wir sind für Sie da, Tag und Nacht. Und helfen Sie einander — eine gute Nachbarschaft ist der beste Schutz. Wenn alle ein bisschen aufpassen, ist die Stadt für alle sicherer."}],"items":[{"q":"Große Verbrechen gehören zu seinen häufigsten Einsätzen.","correct":"nein"},{"q":"Herr Keller arbeitet vor allem für ganz normale Bürger.","correct":"ja"},{"q":"Er rät, bei einem Diebstahl sofort Anzeige zu erstatten.","correct":"ja"},{"q":"Er empfiehlt, die Geldbörse hinten in der Hose zu tragen.","correct":"nein"},{"q":"Er findet, man soll keine Angst haben, die Polizei zu rufen.","correct":"ja"}]}]};
